using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class SurfaceSetNumericalCheck
{
 internal static int Recorded(string root,string input,string output){var r=JsonNode.Parse(File.ReadAllText(input))!.AsObject();var x=SolidQuarterTurnProof.Raw(root,r["originalExecutionRequestId"]!.GetValue<string>()).Value;var observed=SolidQuarterTurnProof.Raw(root,r["observationRequestId"]!.GetValue<string>(),r["observationReceiptSha256"]!.GetValue<string>()).Value;var plan=ArtifactProof.Verified(root,"ownedexecutions",x["operationId"]!.GetValue<string>(),x["planSha256"]!.GetValue<string>(),16000000);var before=ArtifactProof.Verified(root,"responses",plan["inspectionRequestId"]!.GetValue<string>(),plan["inspectionSha256"]!.GetValue<string>(),16000000);var first=new JsonArray(plan["targetEntityKeys"]![0]!.DeepClone());SurfaceSetTranslationProof.Post(before,observed["after"]!.AsObject(),plan["captureBefore"]!.AsObject(),observed["captureObserved"]!.AsObject(),plan["vectorRaw"]!.AsArray(),first,true);Reject(()=>SurfaceSetTranslationProof.Post(before,observed["after"]!.AsObject(),plan["captureBefore"]!.AsObject(),observed["captureObserved"]!.AsObject(),plan["vectorRaw"]!.AsArray(),first),"Recorded normal drift unexpectedly passed strict comparison.");Reject(()=>SurfaceSetTranslationProof.Execution(root,x["operationId"]!.GetValue<string>(),SolidQuarterTurnProof.Raw(root,x["operationId"]!.GetValue<string>()).Sha,false,true),"Old partial schema7 admitted by new execution verifier.");Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["recordedActualNonzeroNormalDriftChecked"]=true,["numericComparisonAccepted"]=true,["strictComparisonRejected"]=true,["oldExecutionStillRejected"]=true,["mutationAuthorityGranted"]=false,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine("PASS actual recorded nonzero normal drift: numerical math accepted, strict math and new execution verifier rejected old partial intent; no CAD/authority.");return 0;}
 static void Reject(Action a,string why){bool rejected=false;try{a();}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException(why);}
 internal static int Run(string input,string output){var rows=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray();int cases=0;
  foreach(var row in rows){string fault=row!["fault"]!.GetValue<string>();if(fault=="source_nonunit")continue;string root=row["root"]!.GetValue<string>(),id=row["executionId"]!.GetValue<string>(),sha=row["executionSha256"]!.GetValue<string>();bool good=fault is "control"or"normal_ulp_drift"or"normal_bound_inside";
   if(good){_=SurfaceSetTranslationProof.Execution(root,id,sha,true,true);var v=SolidQuarterTurnProof.Raw(root,row["verificationId"]!.GetValue<string>(),row["verificationSha256"]!.GetValue<string>()).Value;SurfaceSetTranslationProof.Verified(root,v,row["verificationArguments"]!.AsObject(),true);Reject(()=>SurfaceSetTranslationProof.Execution(root,id,sha,true),"Strict SDK verifier admitted numeric schema8");cases+=3;}
   else if(fault=="execute_only"){var x=SolidQuarterTurnProof.Raw(root,id,sha).Value;SurfaceSetTranslationProof.Receipt(root,x,row["arguments"]!.AsObject(),true);cases++;}
   else{Reject(()=>SurfaceSetTranslationProof.Execution(root,id,sha,false,true),"SDK admitted partial/tampered numerical set "+fault);cases++;}
  }
  var control=rows.Single(r=>r!["fault"]!.GetValue<string>()=="normal_ulp_drift")!.AsObject();string cr=control["root"]!.GetValue<string>();var plan=SurfaceSetTranslationProof.Execution(cr,control["executionId"]!.GetValue<string>(),control["executionSha256"]!.GetValue<string>(),true,true);var before=ArtifactProof.Verified(cr,"responses",plan["inspectionRequestId"]!.GetValue<string>(),plan["inspectionSha256"]!.GetValue<string>(),16000000);var after=ArtifactProof.Verified(cr,"responses",control["verificationArguments"]!["inspectionRequestId"]!.GetValue<string>(),control["verificationArguments"]!["inspectionSha256"]!.GetValue<string>(),16000000);var vraw=SolidQuarterTurnProof.Raw(cr,control["verificationId"]!.GetValue<string>()).Value;
  foreach(var fault in new[]{"target_normal_outside","nontarget_normal_ulp","visibility","target_position","zero_normal"}){var changed=vraw["surfaceCaptureAfter"]!.DeepClone().AsObject();if(fault=="visibility")changed["witnesses"]![0]!["samples"]!["visibility"]![0]=false;else if(fault=="target_position")changed["witnesses"]![0]!["samples"]!["positionsWorldRaw"]![0]![0]=999;else if(fault=="zero_normal")changed["witnesses"]![0]!["samples"]!["normalsWorldRaw"]![0]=new JsonArray(0,0,0);else changed["witnesses"]![fault=="nontarget_normal_ulp"?2:0]!["samples"]!["normalsWorldRaw"]![0]![0]=fault=="nontarget_normal_ulp"?2.220446049250313e-16:1.0001e-12;Reject(()=>SurfaceSetTranslationProof.Post(before,after,plan["captureBefore"]!.AsObject(),changed,plan["vectorRaw"]!.AsArray(),SurfaceSetTranslationProof.Keys(plan),true),"SDK admitted numeric witness fault "+fault);cases++;}
  Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: {cases} Framework/SDK numerical-normal/new-schema/exact-nontarget/partial-step proofs; no CAD.");return 0;
 }
}
